-- Hand-edited: what a notification keeps, whoever writes (buddha_app may update four columns
-- only, below): its account, type, category, target, merge key and creation never change; its
-- first read is kept (#53 AC 5 '다시 들어와도 읽음'); a read one takes no merged event (52-6: the
-- next event after reading makes a new notification); its event count never goes down and its
-- 발생 시각 never back (134-2 raises it only). Raised with the trigger's name as the constraint.
CREATE FUNCTION notifications_kept() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.user_id <> OLD.user_id OR NEW.type <> OLD.type
     OR NEW.category <> OLD.category OR NEW.target <> OLD.target
     OR NEW.merge_key IS DISTINCT FROM OLD.merge_key OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'notification %: its account, type, category, target, merge key and creation never change',
      OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF OLD.read_at IS NOT NULL AND NEW.read_at IS DISTINCT FROM OLD.read_at THEN
    RAISE EXCEPTION 'notification % was read at %: its first read is kept', OLD.id, OLD.read_at
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF OLD.read_at IS NOT NULL AND (NEW.params <> OLD.params OR NEW.event_count <> OLD.event_count
                                  OR NEW.occurred_at <> OLD.occurred_at) THEN
    RAISE EXCEPTION 'notification % was read: only an unread one takes a merged event', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.event_count < OLD.event_count THEN
    RAISE EXCEPTION 'notification %: its event count never goes down', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.occurred_at < OLD.occurred_at THEN
    RAISE EXCEPTION 'notification %: its occurrence time never goes back', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER notifications_kept
  BEFORE UPDATE ON "notifications"
  FOR EACH ROW EXECUTE FUNCTION notifications_kept();--> statement-breakpoint
-- Hand-edited: 0060's body with the inbox (#53): a person's account — a member, an admin — is made
-- with its profile, its user ledger account and its notification inbox. The 운영 마켓메이커 gets
-- none of them (the early RETURN, first as before). Every account is made through this trigger
-- (sign-up, the seed, the test factories), so every open person's account has its inbox.
CREATE OR REPLACE FUNCTION create_profile_for_user() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  -- 32 unambiguous upper-case letters and digits (no 0/O/1/I): 32^4 = 1,048,576 suffixes.
  alphabet CONSTANT text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text;
  i integer;
  attempt integer := 0;
BEGIN
  IF NOT is_human_account_type(NEW.account_type) THEN
    RETURN NEW;
  END IF;
  LOOP
    attempt := attempt + 1;
    candidate := 'user_';
    FOR i IN 1..4 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * 32)::integer, 1);
    END LOOP;
    PERFORM lock_nickname(candidate);
    IF NOT nickname_held(candidate, NEW.id) THEN
      BEGIN
        INSERT INTO profiles (user_id, nickname) VALUES (NEW.id, candidate);
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF attempt >= 10 THEN RAISE; END IF;
      END;
    END IF;
    IF attempt >= 10 THEN
      RAISE EXCEPTION 'no free auto nickname for % after % candidates', NEW.id, attempt
        USING ERRCODE = 'unique_violation';
    END IF;
  END LOOP;
  INSERT INTO ledger_accounts (kind, owner_id) VALUES ('user', NEW.id);
  INSERT INTO notification_inboxes (user_id) VALUES (NEW.id);
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: the inboxes of the accounts made before this migration — every open person's
-- account, through the triggers above (the 운영 마켓메이커 and the closed accounts are left out
-- here and would be refused there). New rows of the new table only; re-runnable.
INSERT INTO notification_inboxes (user_id)
SELECT p.user_id FROM profiles p JOIN "user" u ON u.id = p.user_id
WHERE p.closed_at IS NULL AND is_human_account_type(u.account_type)
ON CONFLICT (user_id) DO NOTHING;--> statement-breakpoint
-- Hand-edited: 0060's closure check with the inbox (#53, 53-7: 탈퇴하면 그 계정의 알림을 한 번에
-- 지움): a closed account keeps no inbox — its notifications and their keys cannot outlive it (the
-- foreign keys' cascade). The rest of the body is 0060's.
CREATE OR REPLACE FUNCTION profiles_closed_completely() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  kept text;
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT FROM "session" WHERE "user_id" = NEW.user_id) THEN 'a session'
    WHEN EXISTS (SELECT FROM "account" WHERE "user_id" = NEW.user_id) THEN 'a sign-in method'
    WHEN EXISTS (SELECT FROM "verification"
                  WHERE "identifier" LIKE 'reset-password:%' AND "value" = NEW.user_id)
      THEN 'a password reset'
    WHEN EXISTS (SELECT FROM "phone_verifications" WHERE "user_id" = NEW.user_id)
      THEN 'its verified number'
    WHEN EXISTS (SELECT FROM "market_watches" WHERE "user_id" = NEW.user_id) THEN 'its watchlist'
    WHEN EXISTS (SELECT FROM "market_searches" WHERE "user_id" = NEW.user_id)
      THEN 'its search history'
    WHEN EXISTS (SELECT FROM "notification_inboxes" WHERE "user_id" = NEW.user_id)
      THEN 'its notifications'
    WHEN EXISTS (SELECT FROM "profile_interest_categories" WHERE "user_id" = NEW.user_id)
      THEN 'its interest categories'
    WHEN EXISTS (SELECT FROM "nickname_holds" WHERE "user_id" = NEW.user_id)
      THEN 'a nickname hold of its own'
    WHEN NEW.time_zone IS NOT NULL THEN 'its time zone'
    WHEN EXISTS (SELECT FROM "market_watch_events" e
                  WHERE e."user_id" = NEW.user_id AND e."action" = 'watch'
                    AND NOT EXISTS (SELECT FROM "market_watch_events" l
                                     WHERE l."user_id" = e."user_id"
                                       AND l."market_id" = e."market_id" AND l."id" > e."id"))
      THEN 'a watch with no unwatch event'
    WHEN EXISTS (SELECT FROM "balances"
                  WHERE "user_id" = NEW.user_id
                    AND ("available_coin" <> 0 OR "locked_coin" <> 0 OR "ledger_coin" <> 0))
      THEN 'Coin'
    WHEN NOT EXISTS (SELECT FROM "user"
                      WHERE "id" = NEW.user_id
                        AND "email" = 'closed_' || NEW.user_id || '@noemail.buddha.local'
                        AND "name" = '' AND "image" IS NULL)
      THEN 'its address, name or photo'
    WHEN EXISTS (SELECT FROM "approval_requests" r
                  WHERE r."status" = 'pending'
                    AND ((r."kind" = 'account_restriction' AND r."target_type" = 'user'
                          AND r."target_id" = NEW.user_id)
                      OR (r."kind" IN ('account_restriction_shorten', 'account_restriction_lift',
                                       'account_restriction_cancel')
                          AND r."target_type" = 'moderation_action'
                          AND EXISTS (SELECT FROM "moderation_actions" a
                                       WHERE a."id"::text = r."target_id"
                                         AND a."user_id" = NEW.user_id))))
      THEN 'a request about it waiting'
  END INTO kept;
  IF kept IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed keeping %', NEW.user_id, kept
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
-- Hand-edited: a dedupe key is never changed (inserted, then gone with its notification), and of a
-- notification buddha_app changes what a merge and a read write: its params, its event count, its
-- 발생 시각 and its read time (the trigger above holds the rest to every role). Both keep INSERT,
-- SELECT and DELETE (the duplicate's own row, the retention); the inbox keeps the default DML — a
-- row lock (FOR KEY SHARE, FOR UPDATE) needs UPDATE privilege on some column.
REVOKE UPDATE ON TABLE "notification_keys" FROM buddha_app;--> statement-breakpoint
REVOKE UPDATE ON TABLE "notifications" FROM buddha_app;--> statement-breakpoint
GRANT UPDATE ("params", "event_count", "occurred_at", "read_at") ON TABLE "notifications" TO buddha_app;